using HRIS.Api.Data; using HRIS.Api.Models; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Repositories;
public class ServiceAwardRepository : IServiceAwardRepository { private readonly AppDbContext _db; public ServiceAwardRepository(AppDbContext db)=>_db=db; public Task<List<ServiceAward>> GetAllAsync()=>_db.ServiceAwards.Include(x=>x.Employee).OrderBy(x=>x.DueDate).ThenBy(x=>x.Employee!.FullName).ToListAsync(); public Task<ServiceAward?> GetByIdAsync(int id)=>_db.ServiceAwards.Include(x=>x.Employee).FirstOrDefaultAsync(x=>x.Id==id); public Task<bool> ExistsAsync(int employeeId,int serviceYears)=>_db.ServiceAwards.AnyAsync(x=>x.EmployeeId==employeeId&&x.ServiceYears==serviceYears); public async Task<ServiceAward> AddAsync(ServiceAward x){_db.ServiceAwards.Add(x);await _db.SaveChangesAsync();return x;} public async Task UpdateAsync(ServiceAward x)=>await _db.SaveChangesAsync(); }
